{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "module TopModule(
    input  logic clk,
    input  logic reset,
    input  logic j,
    input  logic k,
    output logic out
);

    localparam logic OFF = 1'b0;
    localparam logic ON  = 1'b1;

    logic state, state_next;

    // State register with synchronous active-high reset
    always @(posedge clk) begin
        if (reset)
            state <= OFF;
        else
            state <= state_next;
    end

    // Next-state combinational logic
    always @(*) begin
        state_next = state;
        case (state)
            OFF: state_next = (j) ? ON : OFF;
            ON : state_next = (k) ? OFF : ON;
            default: state_next = OFF;
        endcase
    end

    // Moore output logic (depends only on state)
    always @(*) begin
        out = (state == ON);
    end

    // Initialize state to known value to avoid X before first reset
    initial begin
        state = OFF;
    end

endmodule",
