    "new_content": "    // Next-state combinational logic
    always @(*) begin
        // Default: hold state unless transition condition matches
        state_next = state;
        case (state)
            OFF: begin
                // OFF --j=0--> OFF
                // OFF --j=1--> ON
                state_next = (j) ? ON : OFF;
            end
            ON: begin
                // ON --k=0--> ON
                // ON --k=1--> OFF
                state_next = (k) ? OFF : ON;
            end
            default: begin
                // Recover to OFF on illegal state
                state_next = OFF;
            end
        endcase
    end

    // Moore output logic (depends only on current state)
    assign out = (state == ON);
